import unittest
from candidate import same_chars

class TestSameChars(unittest.TestCase):
    def test_same_chars_normal_case(self):
        self.assertTrue(same_chars('eabcdzzzz', 'dddzzzzzzzddeddabc'))

    def test_same_chars_different_character_counts(self):
        self.assertTrue(same_chars('abcd', 'dddddddabc'))

    def test_same_chars_empty_strings(self):
        self.assertTrue(same_chars('', ''))

    def test_same_chars_one_empty_string(self):
        self.assertFalse(same_chars('abcd', ''))

    def test_same_chars_single_character_same(self):
        self.assertTrue(same_chars('x', 'x'))

    def test_same_chars_single_character_different(self):
        self.assertFalse(same_chars('x', 'y'))

    def test_same_chars_case_sensitive(self):
        self.assertFalse(same_chars('A', 'a'))

    def test_same_chars_with_spaces(self):
        self.assertTrue(same_chars('a b c', 'c b a'))

    def test_same_chars_special_characters(self):
        self.assertTrue(same_chars('@#$', '$#@'))

    def test_same_chars_none_input_s0(self):
        with self.assertRaises(TypeError):
            same_chars(None, 'abc')

    def test_same_chars_none_input_s1(self):
        with self.assertRaises(TypeError):
            same_chars('abc', None)

    def test_same_chars_integer_input(self):
        with self.assertRaises(TypeError):
            same_chars(123, 'abc')

    def test_same_chars_unicode_characters(self):
        self.assertTrue(same_chars('αβγ', 'γβα'))

    def test_same_chars_long_strings(self):
        s0 = 'a' * 1000 + 'b'
        s1 = 'b' + 'a' * 1000
        self.assertTrue(same_chars(s0, s1))

    def test_same_chars_reversed_strings(self):
        self.assertTrue(same_chars('abcdef', 'fedcba'))
